<?php $cats=$DB->Query('SELECT * FROM cms_shop_categories ORDER BY display_order,name');$catOptions=[];while($c=mysqli_fetch_assoc($cats))$catOptions[]=$c;$edit=(int)($_GET['edit']??0);$product=$edit?$Admin->one('SELECT * FROM cms_shop_products WHERE id=?','i',[$edit]):null;$products=$DB->Query('SELECT p.*,c.name category_name FROM cms_shop_products p JOIN cms_shop_categories c ON c.id=p.category_id ORDER BY p.id DESC LIMIT 100');?>
<div class="ap-title"><div><span>Boutique interne ParadiseRP</span><h1>Boutique</h1></div><a class="ap-button" href="<?= adm_e(URL) ?>/store" target="_blank">Voir la boutique</a></div><section class="ap-grid"><form class="ap-panel" method="post"><?= admin_csrf() ?><input type="hidden" name="action" value="shop_product_save"><input type="hidden" name="id" value="<?= (int)($product['id']??0) ?>"><h2><?= $product?'Modifier le produit':'Créer un produit' ?></h2><label>Nom<input name="name" required value="<?= adm_e($product['name']??'') ?>"></label><label>Catégorie<select name="category_id"><?php foreach($catOptions as $c):?><option value="<?= $c['id'] ?>" <?= ($product['category_id']??0)==$c['id']?'selected':'' ?>><?= adm_e($c['name']) ?></option><?php endforeach?></select></label><label>Description<textarea name="description"><?= adm_e($product['description']??'') ?></textarea></label><label>Image (URL locale ou HTTPS)<input name="image_url" value="<?= adm_e($product['image_url']??'') ?>"></label><label>Prix<input type="number" min="0" name="price" required value="<?= (int)($product['price']??0) ?>"></label><label>Monnaie<select name="currency"><?php foreach(['credits'=>'Crédits','duckets'=>'Duckets','diamonds'=>'Diamants'] as $k=>$v):?><option value="<?= $k ?>" <?= ($product['currency']??'')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach?></select></label><label>Récompense<select name="reward_type"><?php foreach(['credits'=>'Crédits','duckets'=>'Duckets','diamonds'=>'Diamants','vip'=>'VIP'] as $k=>$v):?><option value="<?= $k ?>" <?= ($product['reward_type']??'')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach?></select></label><label>Quantité / niveau VIP<input type="number" min="1" name="reward_amount" value="<?= (int)($product['reward_amount']??1) ?>"></label><label>Durée VIP en jours<input type="number" min="0" name="duration_days" value="<?= (int)($product['duration_days']??0) ?>"></label><label>Badge configurable<input name="badge" maxlength="30" value="<?= adm_e($product['badge']??'') ?>"></label><label>Stock (vide = illimité)<input type="number" min="0" name="stock" value="<?= adm_e($product['stock']??'') ?>"></label><label>Limite par joueur (vide = aucune)<input type="number" min="1" name="per_user_limit" value="<?= adm_e($product['per_user_limit']??'') ?>"></label><label class="ap-check"><input type="checkbox" name="featured" <?= !empty($product['featured'])?'checked':'' ?>> Mettre en avant</label><label class="ap-check"><input type="checkbox" name="active" <?= !isset($product['active'])||$product['active']?'checked':'' ?>> Actif</label><button data-confirm="Enregistrer ce produit ?">Enregistrer</button></form><form class="ap-panel" method="post"><?= admin_csrf() ?><input type="hidden" name="action" value="shop_category_save"><h2>Nouvelle catégorie</h2><label>Nom<input name="name" required></label><label>Ordre<input type="number" name="display_order" value="50"></label><button>Créer</button><h2 style="margin-top:25px">Catégories</h2><div class="ap-ranks"><?php foreach($catOptions as $c):?><div><span>#<?= $c['id'] ?></span><b><?= adm_e($c['name']) ?><small><?= adm_e($c['slug']) ?></small></b><em><?= $c['active']?'Active':'Inactive' ?></em></div><?php endforeach?></div></form><div class="ap-panel ap-wide"><h2>Produits</h2><div class="ap-table"><table><thead><tr><th>Produit</th><th>Catégorie</th><th>Prix</th><th>Récompense</th><th>État</th><th></th></tr></thead><tbody><?php while($p=mysqli_fetch_assoc($products)):?><tr><td><b><?= adm_e($p['name']) ?></b></td><td><?= adm_e($p['category_name']) ?></td><td><?= (int)$p['price'].' '.adm_e($p['currency']) ?></td><td><?= (int)$p['reward_amount'].' '.adm_e($p['reward_type']) ?></td><td><span class="ap-badge <?= $p['active']?'green':'red' ?>"><?= $p['active']?'Actif':'Inactif' ?></span></td><td><div class="article-row-actions"><a class="ap-button small" href="?tab=catalogue&edit=<?= $p['id'] ?>">Modifier</a><form method="post"><?= admin_csrf() ?><input type="hidden" name="action" value="shop_product_toggle"><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="small" data-confirm="Modifier la disponibilité ?"><?= $p['active']?'Désactiver':'Réactiver' ?></button></form></div></td></tr><?php endwhile?></tbody></table></div></div></section>
